355	export interface UseFieldValidationParameters {
356	  setValidityData: (data: FieldValidityData) => void;
357	  validate: (
358	    value: unknown,
359	    formValues: Form.Values,
360	  ) => string | string[] | null | Promise<string | string[] | null>;
361	  validityData: FieldValidityData;
362	  validationDebounceTime: number;
363	  invalid: boolean;
364	  markedDirtyRef: React.RefObject<boolean>;
365	  state: FieldRootState;
366	  shouldValidateOnChange: () => boolean;
367	  registeredFieldIdRef: React.RefObject<string | undefined>;
368	}
369	
370	export interface UseFieldValidationReturnValue {
371	  getValidationProps: (disabled: boolean, props?: HTMLProps) => HTMLProps;
372	  inputRef: React.RefObject<HTMLInputElement | null>;
373	  registeredInputs: RegisteredInputs;
374	  registerInput: (element: HTMLInputElement, registration: RegisteredInput) => void | (() => void);
375	  getInputControl: () => HTMLElement | null;
376	  commit: (value: unknown) => Promise<void>;
377	  change: (value: unknown) => void;
378	}
