cat > probe.test.tsx <<'EOF'
import * as React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

describe('probe', () => {
  it('A: controlled render count under validationMode=onChange', () => {
    const renderCountRef = { current: 0 };
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Field.Control data-testid="control" value={value} onValueChange={setValue}
            render={(props) => { renderCountRef.current += 1; return <input {...props} />; }} />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    const settled = renderCountRef.current;
    fireEvent.change(control, { target: { value: 'ab' } });
    fireEvent.change(control, { target: { value: 'abc' } });
    console.log('A controlled onChange-mode renders per keystroke:', (renderCountRef.current - settled) / 2);
  });

  it('A2: uncontrolled render count under validationMode=onChange', () => {
    const renderCountRef = { current: 0 };
    render(
      <Field.Root validationMode="onChange" validate={() => null}>
        <Field.Control data-testid="control"
          render={(props) => { renderCountRef.current += 1; return <input {...props} />; }} />
      </Field.Root>,
    );
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    const settled = renderCountRef.current;
    fireEvent.change(control, { target: { value: 'ab' } });
    fireEvent.change(control, { target: { value: 'abc' } });
    console.log('A2 uncontrolled onChange-mode renders per keystroke:', (renderCountRef.current - settled) / 2);
  });

  it('B: programmatic controlled change clears a Form server error', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>set</button>
        </Form>
      );
    }
    render(<App />);
    expect(screen.queryByText('Server error')).not.toBeNull();
    fireEvent.click(screen.getByRole('button'));
    console.log('B server error after programmatic change:', screen.queryByText('Server error') !== null);
  });

  it('C: rejected controlled keystroke does not touch field state', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value="" onValueChange={() => {}} />
      </Field.Root>,
    );
    const root = screen.getByTestId('root');
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    console.log('C rejected keystroke -> dirty:', root.hasAttribute('data-dirty'), 'filled:', root.hasAttribute('data-filled'), 'validate calls:', validate.mock.calls.length);
  });

  it('D: controlled + preventDefault + consumer commits value', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    console.log('D controlled preventDefault -> validate calls:', validate.mock.calls.length, 'server error still shown:', screen.queryByText('Server error') !== null);
  });

  it('E: array controlled value dirty baseline', () => {
    function App() {
      const [value, setValue] = React.useState<any>(['a', 'b']);
      return (
        <Field.Root data-testid="root">
          <Field.Control value={value} onValueChange={(v) => setValue(v.split(','))} />
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    const control = screen.getByRole('textbox');
    const before = root.hasAttribute('data-dirty');
    fireEvent.change(control, { target: { value: 'a,b,c' } });
    const mid = root.hasAttribute('data-dirty');
    fireEvent.change(control, { target: { value: 'a,b' } });
    console.log('E array dirty: initial', before, 'after change', mid, 'after return', root.hasAttribute('data-dirty'));
  });

  it('F: canceled uncontrolled change still flips dirty/filled', () => {
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={() => null}>
        <Field.Control onValueChange={(v, d) => d.cancel()} />
      </Field.Root>,
    );
    const root = screen.getByTestId('root');
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    console.log('F canceled -> dirty:', root.hasAttribute('data-dirty'), 'filled:', root.hasAttribute('data-filled'));
  });

  it('G: async validator stale publish on programmatic change', async () => {
    let resolveFirst: (v: string | null) => void = () => {};
    let call = 0;
    const validate = vi.fn((_v: unknown) => {
      call += 1;
      if (call === 1) { return new Promise<string | null>((res) => { resolveFirst = res; }); }
      return null;
    });
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error />
          <button type="button" onClick={() => setValue('ok')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'bad' } });
    fireEvent.click(screen.getByRole('button'));
    await act(async () => { resolveFirst('stale error'); await Promise.resolve(); await Promise.resolve(); });
    console.log('G stale error shown:', screen.queryByText('stale error') !== null, 'validate calls:', validate.mock.calls.length);
  });
});
EOF
