import * as React from 'react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);
const ERRORS = { message: 'Server error' };

describe('probe2', () => {
  it('B2: programmatic controlled change clears a Form server error (stable errors)', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={ERRORS}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>set</button>
        </Form>
      );
    }
    render(<App />);
    expect(screen.queryByText('Server error')).not.toBeNull();
    fireEvent.click(screen.getByRole('button'));
    console.log('B2 server error after programmatic change:', screen.queryByText('Server error') !== null);
  });

  it('B3: user typing in controlled input clears a Form server error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={ERRORS}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    console.log('B3 server error after typing (controlled):', screen.queryByText('Server error') !== null);
  });

  it('D2: controlled + preventDefault + consumer commits value (stable errors)', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={ERRORS}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    console.log('D2 controlled preventDefault -> validate calls:', validate.mock.calls.length, 'server error still shown:', screen.queryByText('Server error') !== null);
  });
});
EOF
