import * as React from 'react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';

afterEach(() => cleanup());

function log(...args: unknown[]) {
  // eslint-disable-next-line no-console
  console.log('[validator]', ...args);
}

describe('finding #1: onBlur mode + controlled + trim-on-blur', () => {
  function makeApp(trim: boolean, validate: (v: unknown) => any) {
    return function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onBlur" validate={validate}>
          <Field.Control
            value={value}
            onValueChange={setValue}
            onBlur={trim ? () => setValue((v) => v.trim()) : undefined}
          />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    };
  }

  it('F1-sync-trim: sync validator, consumer trims on blur', () => {
    const validate = vi.fn((v: unknown) => (String(v).length < 5 ? 'Too short' : null));
    const App = makeApp(true, validate);
    render(<App />);
    const input = screen.getByRole('textbox') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'ab ' } });
    fireEvent.blur(input);
    const error = screen.queryByTestId('error');
    log('F1-sync-trim validate calls', validate.mock.calls.map((c) => JSON.stringify(c[0])));
    log('F1-sync-trim input value', JSON.stringify(input.value));
    log('F1-sync-trim error present', error !== null, 'text', error?.textContent);
    log('F1-sync-trim aria-invalid', input.getAttribute('aria-invalid'));
    log('F1-sync-trim root data-invalid', screen.getByTestId('root').hasAttribute('data-invalid'));
    expect(validate).toHaveBeenCalled();
  });

  it('F1-sync-notrim: sync validator, no trim (control)', () => {
    const validate = vi.fn((v: unknown) => (String(v).length < 5 ? 'Too short' : null));
    const App = makeApp(false, validate);
    render(<App />);
    const input = screen.getByRole('textbox') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'ab ' } });
    fireEvent.blur(input);
    const error = screen.queryByTestId('error');
    log('F1-sync-notrim validate calls', validate.mock.calls.map((c) => JSON.stringify(c[0])));
    log('F1-sync-notrim error present', error !== null, 'text', error?.textContent);
    log('F1-sync-notrim aria-invalid', input.getAttribute('aria-invalid'));
  });

  it('F1-async-trim: async validator, consumer trims on blur', async () => {
    const validate = vi.fn(async (v: unknown) => (String(v).length < 5 ? 'Too short' : null));
    const App = makeApp(true, validate);
    render(<App />);
    const input = screen.getByRole('textbox') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'ab ' } });
    fireEvent.blur(input);
    await act(async () => {
      await new Promise((r) => setTimeout(r, 20));
    });
    const error = screen.queryByTestId('error');
    log('F1-async-trim validate calls', validate.mock.calls.map((c) => JSON.stringify(c[0])));
    log('F1-async-trim error present', error !== null, 'text', error?.textContent);
    log('F1-async-trim aria-invalid', input.getAttribute('aria-invalid'));
  });

  it('F1-async-notrim: async validator, no trim (control)', async () => {
    const validate = vi.fn(async (v: unknown) => (String(v).length < 5 ? 'Too short' : null));
    const App = makeApp(false, validate);
    render(<App />);
    const input = screen.getByRole('textbox') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'ab ' } });
    fireEvent.blur(input);
    await act(async () => {
      await new Promise((r) => setTimeout(r, 20));
    });
    const error = screen.queryByTestId('error');
    log('F1-async-notrim validate calls', validate.mock.calls.map((c) => JSON.stringify(c[0])));
    log('F1-async-notrim error present', error !== null, 'text', error?.textContent);
    log('F1-async-notrim aria-invalid', input.getAttribute('aria-invalid'));
  });
});

describe('finding #3: renders per keystroke, validationMode=onChange', () => {
  it('F3-controlled-onChange', () => {
    const renderCount = { current: 0 };
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Field.Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props) => {
              renderCount.current += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
